import { Component, Event, EventEmitter, h, Host, Prop } from '@stencil/core';

@Component({
  tag: 'groupui-divider',
  styleUrl: 'divider.scss',
  shadow: true,
})
export class Divider {
  /**
   * activates an inverted presentation
   */
  @Prop({ reflect: true }) readonly inverted: boolean;

  /**
   * divider stretches vertically; only works in containers with a fixed height - set height explicitly if you want to use it elsewhere
   */
  @Prop({ reflect: true }) readonly vertical: boolean;

  /**
   * divider shows as dashed
   */
  @Prop({ reflect: true }) readonly dashed: boolean;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  render() {
    return (
      <Host aria-hidden="true">
        <hr aria-orientation={this.vertical ? 'vertical' : null} />
      </Host>
    );
  }
}
